ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS inventory_reserved_at timestamptz;
CREATE TABLE IF NOT EXISTS public.order_inventory_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,balance_id uuid NOT NULL REFERENCES public.inventory_balances(id) ON DELETE RESTRICT,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE RESTRICT,quantity integer NOT NULL CHECK(quantity>0),consumed_at timestamptz,released_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS order_inventory_reservations_active_idx ON public.order_inventory_reservations(order_id,balance_id,product_id) WHERE consumed_at IS NULL AND released_at IS NULL;
ALTER TABLE public.order_inventory_reservations ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.order_inventory_reservations FROM anon,authenticated;
CREATE OR REPLACE FUNCTION public.reserve_order_inventory(_order_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE ord public.orders%ROWTYPE;item jsonb;pid uuid;needed integer;remaining integer;bal record;take_qty integer;BEGIN SELECT * INTO ord FROM public.orders WHERE id=_order_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'order not found';END IF;IF ord.user_id<>auth.uid() AND NOT private.is_admin() THEN RAISE EXCEPTION 'not authorized';END IF;IF ord.payment_status<>'pending' THEN RAISE EXCEPTION 'order is not pending';END IF;IF ord.inventory_reserved_at IS NOT NULL THEN RETURN true;END IF;FOR item IN SELECT * FROM jsonb_array_elements(ord.items::jsonb) LOOP needed:=COALESCE((item->>'qty')::integer,(item->>'quantity')::integer,0);pid:=NULL;IF item?'product_id' AND NULLIF(item->>'product_id','') IS NOT NULL THEN pid:=(item->>'product_id')::uuid;ELSE SELECT id INTO pid FROM public.products WHERE name=item->>'name' AND active=true LIMIT 1;END IF;IF pid IS NULL OR needed<=0 THEN RAISE EXCEPTION 'invalid order item';END IF;SELECT COALESCE(SUM(quantity-reserved),0)::integer INTO remaining FROM public.inventory_balances WHERE product_id=pid;IF remaining<needed THEN RAISE EXCEPTION 'insufficient inventory';END IF;remaining:=needed;FOR bal IN SELECT id,quantity,reserved FROM public.inventory_balances WHERE product_id=pid AND quantity>reserved ORDER BY (quantity-reserved) DESC,updated_at ASC FOR UPDATE LOOP EXIT WHEN remaining=0;take_qty:=LEAST(remaining,bal.quantity-bal.reserved);UPDATE public.inventory_balances SET reserved=reserved+take_qty,updated_at=now() WHERE id=bal.id;INSERT INTO public.order_inventory_reservations(order_id,balance_id,product_id,quantity) VALUES(_order_id,bal.id,pid,take_qty);remaining:=remaining-take_qty;END LOOP;END LOOP;UPDATE public.orders SET inventory_reserved_at=now() WHERE id=_order_id;RETURN true;END;$$;
REVOKE ALL ON FUNCTION public.reserve_order_inventory(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.reserve_order_inventory(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.allocate_paid_order_inventory(_order_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE ord public.orders%ROWTYPE;r record;BEGIN SELECT * INTO ord FROM public.orders WHERE id=_order_id FOR UPDATE;IF NOT FOUND OR ord.payment_status<>'paid' THEN RETURN false;END IF;IF ord.inventory_allocated_at IS NOT NULL THEN RETURN true;END IF;IF ord.inventory_reserved_at IS NULL THEN RAISE EXCEPTION 'paid order has no inventory reservation';END IF;FOR r IN SELECT * FROM public.order_inventory_reservations WHERE order_id=_order_id AND consumed_at IS NULL AND released_at IS NULL FOR UPDATE LOOP UPDATE public.inventory_balances SET quantity=quantity-r.quantity,reserved=reserved-r.quantity,updated_at=now() WHERE id=r.balance_id AND reserved>=r.quantity AND quantity>=r.quantity;IF NOT FOUND THEN RAISE EXCEPTION 'reservation balance inconsistent';END IF;UPDATE public.order_inventory_reservations SET consumed_at=now() WHERE id=r.id;END LOOP;UPDATE public.orders SET inventory_allocated_at=now() WHERE id=_order_id;RETURN true;END;$$;
CREATE OR REPLACE FUNCTION public.release_order_inventory(_order_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r record;BEGIN FOR r IN SELECT * FROM public.order_inventory_reservations WHERE order_id=_order_id AND consumed_at IS NULL AND released_at IS NULL FOR UPDATE LOOP UPDATE public.inventory_balances SET reserved=GREATEST(0,reserved-r.quantity),updated_at=now() WHERE id=r.balance_id;UPDATE public.order_inventory_reservations SET released_at=now() WHERE id=r.id;END LOOP;RETURN true;END;$$;
REVOKE ALL ON FUNCTION public.release_order_inventory(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.release_order_inventory(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.orders_inventory_lifecycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NEW.payment_status='paid' AND OLD.payment_status IS DISTINCT FROM 'paid' THEN PERFORM public.allocate_paid_order_inventory(NEW.id);ELSIF NEW.payment_status IN('expired','cancelled','canceled') AND OLD.payment_status IS DISTINCT FROM NEW.payment_status THEN PERFORM public.release_order_inventory(NEW.id);END IF;RETURN NEW;END;$$;
DROP TRIGGER IF EXISTS orders_allocate_inventory_after_payment ON public.orders;DROP TRIGGER IF EXISTS orders_inventory_lifecycle ON public.orders;CREATE TRIGGER orders_inventory_lifecycle AFTER UPDATE OF payment_status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.orders_inventory_lifecycle();